1: /**
2:  * LSPTool — language server protocol operations for code intelligence.
3:  */
4: 
5: import type { ToolContext, ToolDefinition } from "@cjhyy/code-shell-core/extension";
6: import { getLSPManager } from "../lsp/manager.js";
7: import { detectLSPServer } from "../lsp/servers.js";
8: import { pathToFileURL } from "node:url";
9: import { isAbsolute, resolve } from "node:path";
10: 
11: /**
12:  * How long to wait for `textDocument/publishDiagnostics` after opening a file.
13:  *
14:  * A cold server has to index the project first, so this is a deadline rather
15:  * than an expected duration — timing out reports "still indexing" instead of
16:  * silently claiming the file is clean.
17:  */
18: const DIAGNOSTICS_TIMEOUT_MS = 10_000;
19: 
20: const DIAGNOSTIC_SEVERITY: Record<number, string> = {
21:   1: "error",
22:   2: "warning",
23:   3: "info",
24:   4: "hint",
25: };
26: 
27: interface LspDiagnostic {
28:   message: string;
29:   severity?: number;
30:   source?: string;
31:   range?: { start?: { line: number; character: number } };
32: }
33: 
34: export const lspToolDef: ToolDefinition = {
35:   name: "LSP",
36:   description:
37:     "Use Language Server Protocol for code intelligence operations. " +
38:     "Available actions: goToDefinition, findReferences, hover, getDiagnostics, getSymbols. " +
39:     "Requires a language server to be installed for the target language.",
40:   inputSchema: {
41:     type: "object",
42:     properties: {
43:       action: {
44:         type: "string",
45:         enum: ["goToDefinition", "findReferences", "hover", "getDiagnostics", "getSymbols"],
46:         description: "The LSP operation to perform",
47:       },
48:       file_path: {
49:         type: "string",
50:         description: "Absolute path to the file",
51:       },
52:       line: {
53:         type: "number",
54:         description: "Line number (0-based). Required for goToDefinition, findReferences, hover.",
55:       },
56:       character: {
57:         type: "number",
58:         description:
59:           "Character offset (0-based). Required for goToDefinition, findReferences, hover.",
60:       },
61:     },
62:     required: ["action", "file_path"],
63:   },
64: };
65: 
66: export async function lspTool(args: Record<string, unknown>, ctx?: ToolContext): Promise<string> {
67:   const action = args.action as string;
68:   const rawPath = args.file_path as string;
69:   const line = (args.line as number) ?? 0;
70:   const character = (args.character as number) ?? 0;
71: 
72:   if (!rawPath) return "Error: file_path is required";
73:   const cwd = ctx?.cwd ?? process.cwd();
74:   const filePath = isAbsolute(rawPath) ? rawPath : resolve(cwd, rawPath);
75: 
76:   // Lazily create the manager for THIS workspace. Previously this read a
77:   // process-wide singleton that no host ever initialized, so the tool was
78:   // advertised to the agent but always answered "LSP is not initialized".
79:   const manager = getLSPManager(cwd);
80:   if (!manager) return "Error: LSP is not initialized. Language servers are not available.";
81: 
82:   // Detect the appropriate server
83:   const serverConfig = detectLSPServer(filePath);
84:   if (!serverConfig) return `Error: No language server configured for ${filePath}`;
85: 
86:   const client = await manager.getClient(serverConfig.name);
87:   if (!client) {
88:     return `Error: Language server "${serverConfig.name}" is not available. Install: ${serverConfig.installHint}`;
89:   }
90: 
91:   const uri = pathToFileURL(filePath).href;
92:   const position = { line, character };
93: 
94:   try {
95:     switch (action) {
96:       case "goToDefinition": {
97:         const result = await client.request("textDocument/definition", {
98:           textDocument: { uri },
99:           position,
100:         });
101:         return formatLocationResult(result, "Definition");
102:       }
103: 
104:       case "findReferences": {
105:         const result = await client.request("textDocument/references", {
106:           textDocument: { uri },
107:           position,
108:           context: { includeDeclaration: true },
109:         });
110:         return formatLocationResult(result, "References");

40:   constructor(
41:     private readonly command: string,
42:     private readonly args: string[] = [],
43:     private readonly cwd?: string,
44:   ) {
45:     super();
46:   }
47: 
48:   async start(): Promise<void> {
49:     this.process = spawn(this.command, this.args, {
50:       cwd: this.cwd,
51:       stdio: ["pipe", "pipe", "pipe"],
52:     });
53: 
54:     this.process.stdout?.on("data", (data: Buffer) => this.handleData(data));
55:     this.process.stderr?.on("data", (_data: Buffer) => {
56:       // LSP servers often log to stderr — ignore
57:     });
58:     this.process.on("exit", (code) => {
59:       this.emit("exit", code);
60:       this.rejectAll(new Error(`LSP server exited with code ${code}`));
61:     });
62: 
63:     // Don't keep the event loop alive solely for the LSP child.
64:     // Call after listeners are wired so event registration doesn't re-ref.
65:     this.process.unref();
66:   }
67: 
68:   async initialize(rootUri: string): Promise<unknown> {
69:     const result = await this.request("initialize", {
70:       processId: process.pid,
71:       rootUri,
72:       capabilities: {
73:         textDocument: {
74:           definition: { dynamicRegistration: false },
75:           references: { dynamicRegistration: false },
76:           hover: { contentFormat: ["plaintext", "markdown"] },
77:           documentSymbol: { dynamicRegistration: false },
78:           completion: { dynamicRegistration: false },
79:         },
80:         workspace: {
81:           symbol: { dynamicRegistration: false },
82:         },
83:       },
84:     });
85:     await this.notify("initialized", {});
86:     this.initialized = true;

130:   async shutdown(): Promise<void> {
131:     if (!this.process) return;
132:     try {
133:       await this.request("shutdown", {});
134:       await this.notify("exit", {});
135:     } catch {
136:       // Force kill
137:     }
138:     this.process.stdout?.removeAllListeners();
139:     this.process.stderr?.removeAllListeners();
140:     this.process.removeAllListeners();
141:     this.process.kill();
142:     this.process = undefined;
143:     // Drain pending requests
144:     for (const { reject } of this.pending.values()) {
145:       reject(new Error("LSP server shut down"));
146:     }
147:     this.pending.clear();
148:   }
149: 
150:   get isInitialized(): boolean {
151:     return this.initialized;
152:   }
153: 
154:   get isAlive(): boolean {
155:     return this.process !== undefined && !this.process.killed;
156:   }

1: import { describe, test, expect } from "bun:test";
2: import { pathToFileURL } from "node:url";
3: import { rootUriToPath } from "./root-path.js";
4: 
5: // Regression: LSPServerManager derived the workspace path with
6: // `rootUri.replace("file://", "")` (review-2026-05-30, high). That only strips
7: // the first "file://" and mangles Windows URLs: file:///C:/x → /C:/x (invalid).
8: // fileURLToPath handles platform paths and percent-decoding correctly.
9: 
10: describe("coding rootUriToPath", () => {
11:   test("round-trips a posix path through file:// URL", () => {
12:     const p = "/Users/me/proj";
13:     expect(rootUriToPath(pathToFileURL(p).href)).toBe(p);
14:   });
15: 
16:   test("decodes percent-encoded spaces (replace() would leave %20)", () => {
17:     const p = "/Users/me/my project";
18:     const uri = pathToFileURL(p).href; // .../my%20project
19:     expect(uri).toContain("%20");
20:     expect(rootUriToPath(uri)).toBe(p);
21:   });
22: 
23:   test("differs from the naive replace() on a percent-encoded path", () => {
24:     // The concrete bug the fix removes (verifiable on any platform): naive
25:     // replace() leaves %20 in the path, fileURLToPath decodes it.
26:     const p = "/Users/me/a b/proj";
27:     const uri = pathToFileURL(p).href;
28:     const naive = uri.replace("file://", "");
29:     expect(naive).toContain("%20"); // buggy: still encoded
30:     expect(rootUriToPath(uri)).toBe(p); // fixed: decoded, equals original
31:     expect(rootUriToPath(uri)).not.toBe(naive);
32:   });
33: });

1: // LSP manager lifecycle.
2: //
3: // The manager used to be a single process-wide singleton created only by
4: // `initializeLSPManager()` — which NO host ever called. The `LSP` tool was
5: // registered and advertised to the agent, but its first act is `getLSPManager()`,
6: // so every invocation returned "LSP is not initialized". The capability was dead
7: // in every product surface.
8: //
9: // It is now created lazily per workspace root, which also fixes the design flaw
10: // behind the singleton: one process can span several workspaces (worktrees,
11: // sub-agents) while a language server is rooted at exactly one directory.
12: import { afterEach, describe, expect, test } from "bun:test";
13: import { mkdtempSync, rmSync } from "node:fs";
14: import { tmpdir } from "node:os";
15: import { join } from "node:path";
16: import {
17:   getLSPManager,
18:   initializeLSPManager,
19:   shutdownAllLSPManagers,
20:   shutdownLSPManager,
21: } from "./manager.js";
22: 
23: const dirs: string[] = [];
24: function workspace(): string {
25:   const d = mkdtempSync(join(tmpdir(), "lsp-ws-"));
26:   dirs.push(d);
27:   return d;
28: }
29: 
30: afterEach(async () => {
31:   await shutdownAllLSPManagers();
32:   for (const d of dirs.splice(0)) rmSync(d, { recursive: true, force: true });
33: });
34: 
35: describe("LSP manager registry", () => {
36:   test("getLSPManager creates one on first use instead of returning undefined", async () => {
37:     // The whole bug: this returned undefined forever because nothing called
38:     // initializeLSPManager().
39:     const root = workspace();
40:     expect(getLSPManager(root, { create: false })).toBeUndefined();
41:     expect(getLSPManager(root)).toBeDefined();
42:   });
43: 
44:   test("the same root reuses one manager", () => {
45:     const root = workspace();
46:     const first = getLSPManager(root);
47:     expect(first).toBeDefined();
48:     expect(getLSPManager(root)).toBe(first!);
49:     expect(initializeLSPManager(root)).toBe(first!);
50:   });
51: 
52:   test("different roots get different managers", () => {
53:     // A language server is rooted at one directory; two worktrees must not share.
54:     const a = workspace();
55:     const b = workspace();
56:     expect(getLSPManager(a)).not.toBe(getLSPManager(b));
57:   });
58: 
59:   test("create:false observes without spawning", () => {
60:     const root = workspace();
61:     expect(getLSPManager(root, { create: false })).toBeUndefined();
62:     // Still nothing was registered.
63:     expect(getLSPManager(root, { create: false })).toBeUndefined();
64:   });
65: 
66:   test("shutdown forgets the workspace so a later call builds a fresh one", async () => {
67:     const root = workspace();
68:     const first = getLSPManager(root);
69:     await shutdownLSPManager(root);
70:     expect(getLSPManager(root, { create: false })).toBeUndefined();
71:     expect(getLSPManager(root)).not.toBe(first);
72:   });
73: 
74:   test("shutting down an unknown workspace is a no-op", async () => {
75:     await shutdownLSPManager(join(tmpdir(), "never-registered"));
76:   });
77: 
78:   test("the no-argument form resolves only when unambiguous", async () => {
79:     // Back-compat for call sites without workspace context.
80:     expect(getLSPManager()).toBeUndefined();
81:     const only = getLSPManager(workspace());
82:     expect(getLSPManager()).toBe(only);
83:     // With two workspaces there is no single right answer, so it declines.
84:     getLSPManager(workspace());
85:     expect(getLSPManager()).toBeUndefined();
86:   });
87: 
88:   test("the live workspace set is bounded — oldest are evicted", () => {
89:     // Per-workspace managers fixed the single-cwd bug but made the map
90:     // unbounded: a long session touching many worktrees would keep a language
91:     // server per root alive forever.
92:     const roots = Array.from({ length: 6 }, () => workspace());
93:     for (const root of roots) getLSPManager(root);
94: 
95:     const live = roots.filter((root) => getLSPManager(root, { create: false }) !== undefined);
96:     expect(live.length).toBeLessThanOrEqual(4);
97:     // The most recently used ones survive.
98:     expect(getLSPManager(roots[5]!, { create: false })).toBeDefined();
99:     expect(getLSPManager(roots[0]!, { create: false })).toBeUndefined();
100:   });
101: 
102:   test("recency is refreshed on read, so an active workspace is not evicted", () => {
103:     const roots = Array.from({ length: 4 }, () => workspace());
104:     for (const root of roots) getLSPManager(root);
105: 
106:     // Keep using the OLDEST one, then push the set past the cap.
107:     const keepAlive = roots[0]!;
108:     expect(getLSPManager(keepAlive, { create: false })).toBeDefined();
109:     getLSPManager(workspace());
110:     getLSPManager(workspace());
111: 
112:     // It survived because reads count as use; without that it would have been
113:     // the first victim purely for having been created earliest.
114:     expect(getLSPManager(keepAlive, { create: false })).toBeDefined();
115:   });
116: 
117:   test("an evicted workspace simply rebuilds on next use", () => {
118:     const roots = Array.from({ length: 6 }, () => workspace());
119:     for (const root of roots) getLSPManager(root);
120:     const evicted = roots[0]!;
121:     expect(getLSPManager(evicted, { create: false })).toBeUndefined();
122:     // Cold start, not an error.
123:     expect(getLSPManager(evicted)).toBeDefined();
124:   });
125: 
126:   test("a fresh manager reports its servers as stopped, not connected", () => {
127:     const manager = getLSPManager(workspace())!;
128:     expect(manager.isConnected()).toBe(false);
129:     // Built-in servers are registered but not started — lazy by design, so a
130:     // session that never uses LSP pays for no processes.
131:     expect(manager.listServers().length).toBeGreaterThan(0);
132:     expect(manager.listServers().every((s) => s.state === "stopped")).toBe(true);
133:   });
134: });
